  #include "mylib.h"

  void my_static_function() {
      // Function implementation
  }
  ```

- **Main Application (app.c)**:
  ```c
  #include <stdio.h>
  #include "mylib.h"

  int main() {
      my_static_function(); // Calls the static function
      return 0;
  }
  ```

